refentry.refsect1:
&reftitle.description;
stringfalseftp_mkdir FTP\Connectionftp stringdirectory
Crea la directory directory specificata sul server FTP.

&reftitle.parameters;




   ftp

     &ftp.parameter.ftp;



   directory



     Il nome della directory che verrà creata.

&reftitle.errors;

 Emette un errore di livello E_WARNING se la directory
 esiste già o se i relativi permessi impediscono di creare la directory.

  &reftitle.examples;



    Esempio di ftp_mkdir


<?php

$dir = 'www';

// stabilisce la connessione
$ftp = ftp_connect($ftp_server);

// si collega con nome utente e password
$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass);

// prova a creare la directory $dir
if (ftp_mkdir($ftp, $dir)) {
 echo "$dir creata correttamente\n";
} else {
 echo "Si è verificato un problema durante la creazione di $dir\n";
}

// chiude la connessione
ftp_close($ftp);
?>
